  1	package com.example.application.service;
  2	
  3	import com.example.api.dto.*;
  4	import com.example.application.exception.*;
  5	import com.example.domain.entity.*;
  6	import com.example.domain.enums.*;
  7	import com.example.domain.repository.OrderRepository;
  8	import org.springframework.stereotype.Service;
  9	import java.math.BigDecimal;
 10	import java.time.Instant;
 11	import java.util.*;
 12	
 13	@Service
 14	public class OrderService {
 15	
 16	    private final OrderRepository orderRepository;
 17	    private final ProductService productService;
 18	    private final CustomerService customerService;
 19	    private final NotificationService notificationService;
 20	    private final OrderSummaryCalculator summaryCalculator;
 21	    private final ValidationService validationService;
 22	    private final CouponValidator couponValidator;
 23	    private final TransLogService transLogService;
 24	
 25	    private static final long PAYMENT_TIMEOUT = 48 * 60 * 60 * 1000;
 26	
 27	    public OrderService(
 28	            OrderRepository orderRepository,
 29	            ProductService productService,
 30	            CustomerService customerService,
 31	            NotificationService notificationService,
 32	            OrderSummaryCalculator summaryCalculator,
 33	            TransLogService transLogService) {
 34	        this.orderRepository = orderRepository;
 35	        this.productService = productService;
 36	        this.customerService = customerService;
 37	        this.notificationService = notificationService;
 38	        this.summaryCalculator = summaryCalculator;
 39	        this.validationService = new ValidationService(productService);
 40	        this.couponValidator = new CouponValidator(orderRepository);
 41	        this.transLogService = transLogService;
 42	    }
 43	
 44	    public OrderSummary calculateSummary(CheckoutRequestDto request) {
 45	        validationService.validateCheckout(request);
 46	        validateAndAdjustForTransLog(request);
 47	        BigDecimal productsSubtotal = summaryCalculator.calculateProductsSubtotal(request);
 48	        couponValidator.validate(request, productsSubtotal);
 49	        validatePaymentMethod(request, productsSubtotal);
 50	
 51	        return summaryCalculator.calculate(request);
 52	    }
 53	
 54	    public Order createOrder(CheckoutRequestDto request) {
 55	        OrderSummary summary = calculateSummary(request);
 56	
 57	        Order order = new Order(request.getCustomer().getCpf(), request.getCustomer().getEmail(), summary);
 58	
 59	        for (var item : request.getItems()) {
 60	            order.addItem(new OrderItem(item.getSku(), item.getQuantity()));
 61	        }
 62	
 63	        return orderRepository.save(order);
 64	    }
 65	
 66	    public Order getOrder(String orderId) {
 67	        Order order = orderRepository.findById(orderId).orElse(null);
 68	        if (order == null) {
 69	            throw new OrderNotFoundException();
 70	        }
 71	        return order;
 72	    }
 73	
 74	    public Order processPayment(String orderId, PaymentRequestDto paymentRequest) {
 75	        if (paymentRequest.getTransactionId() == null || paymentRequest.getPaidAt() == null) {
 76	            throw new InvalidOrderException();
 77	        }
 78	
 79	        Order order = getOrder(orderId);
 80	
 81	        if (order.getLastSuccessfulTransactionId() != null &&
 82	            order.getLastSuccessfulTransactionId().equals(paymentRequest.getTransactionId())) {
 83	            return order;
 84	        }
 85	
 86	        if (!order.getStatus().equals(OrderStatus.AWAITING_PAYMENT)) {
 87	            throw new OperationNotAllowedException();
 88	        }
 89	
 90	        if (!order.isPaidWithinTimeout(PAYMENT_TIMEOUT)) {
 91	            order.setStatus(OrderStatus.CANCELLED);
 92	            orderRepository.save(order);
 93	            notificationService.createNotification(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId);
 94	            throw new OrderExpiredException();
 95	        }
 96	
 97	        if (!validateStockForPayment(order)) {
 98	            order.setStatus(OrderStatus.CANCELLED);
 99	            orderRepository.save(order);
100	            notificationService.createNotification(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId);
101	            throw new InsufficientStockException();
102	        }
103	
104	        order.setStatus(OrderStatus.PAID);
105	        order.setPaidAt(paymentRequest.getPaidAt());
106	        order.setLastSuccessfulTransactionId(paymentRequest.getTransactionId());
107	        orderRepository.save(order);
108	
109	        decreaseStock(order);
110	        addCreditToCustomer(order);
111	
112	        notificationService.createNotification(order.getCustomerCpf(), NotificationType.PAYMENT_APPROVED, orderId);
113	
114	        return order;
115	    }
116	
117	    public Order shipOrder(String orderId, ShipmentRequestDto shipmentRequest) {
118	        if (shipmentRequest.getTrackingCode() == null) {
119	            throw new InvalidOrderException();
120	        }
121	
122	        Order order = getOrder(orderId);
123	
124	        if (!order.getStatus().equals(OrderStatus.PAID)) {
125	            throw new OperationNotAllowedException();
126	        }
127	
128	        order.setStatus(OrderStatus.SHIPPED);
129	        order.setTrackingCode(shipmentRequest.getTrackingCode());
130	        orderRepository.save(order);
131	
132	        notificationService.createNotification(order.getCustomerCpf(), NotificationType.ORDER_SHIPPED, orderId);
133	
134	        return order;
135	    }
136	
137	    public Order deliverOrder(String orderId) {
138	        Order order = getOrder(orderId);
139	
140	        if (!order.getStatus().equals(OrderStatus.SHIPPED)) {
141	            throw new OperationNotAllowedException();
142	        }
143	
144	        order.setStatus(OrderStatus.DELIVERED);
145	        orderRepository.save(order);
146	
147	        return order;
148	    }
149	
150	    public Order cancelOrder(String orderId) {
151	        Order order = getOrder(orderId);
152	
153	        if (order.getStatus().equals(OrderStatus.SHIPPED) || order.getStatus().equals(OrderStatus.DELIVERED)) {
154	            throw new OperationNotAllowedException();
155	        }
156	
157	        if (order.getStatus().equals(OrderStatus.PAID)) {
158	            increaseStock(order);
159	            subtractCreditFromCustomer(order);
160	        }
161	
162	        order.setStatus(OrderStatus.CANCELLED);
163	        orderRepository.save(order);
164	
165	        notificationService.createNotification(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId);
166	
167	        return order;
168	    }
169	
170	    private void validateAndAdjustForTransLog(CheckoutRequestDto request) {
171	        ShippingMethod method = ShippingMethod.valueOf(request.getShippingMethod());
172	        if (method == ShippingMethod.ECONOMY || method == ShippingMethod.EXPRESS) {
173	            OrderSummaryCalculator.ShippingQuote quote = transLogService.getQuote(
174	                    request.getZipCode(),
175	                    calculateTotalWeight(request),
176	                    method
177	            );
178	            if (quote == null) {
179	                throw new ShippingMethodUnavailableException();
180	            }
181	        }
182	    }
183	
184	    private void validatePaymentMethod(CheckoutRequestDto request, BigDecimal productsSubtotal) {
185	        PaymentMethod method = PaymentMethod.valueOf(request.getPaymentMethod());
186	        if (method == PaymentMethod.BANK_SLIP) {
187	            OrderSummary summary = summaryCalculator.calculate(request);
188	            if (summary.getFinalTotal().compareTo(new BigDecimal("1000")) > 0) {
189	                throw new PaymentMethodUnavailableException();
190	            }
191	        }
192	    }
193	
194	    private boolean validateStockForPayment(Order order) {
195	        for (OrderItem item : order.getItems()) {
196	            Product product = productService.getProduct(item.getSku());
197	            if (product == null || product.getStock() < item.getQuantity()) {
198	                return false;
199	            }
200	        }
201	        return true;
202	    }
203	
204	    private void decreaseStock(Order order) {
205	        for (OrderItem item : order.getItems()) {
206	            productService.updateStock(item.getSku(), -item.getQuantity());
207	        }
208	    }
209	
210	    private void increaseStock(Order order) {
211	        for (OrderItem item : order.getItems()) {
212	            productService.updateStock(item.getSku(), item.getQuantity());
213	        }
214	    }
215	
216	    private void addCreditToCustomer(Order order) {
217	        customerService.addCredit(order.getCustomerCpf(), order.getSummary().getNextPurchaseCredit());
218	    }
219	
220	    private void subtractCreditFromCustomer(Order order) {
221	        customerService.subtractCredit(order.getCustomerCpf(), order.getSummary().getNextPurchaseCredit());
222	    }
223	
224	    private BigDecimal calculateTotalWeight(CheckoutRequestDto request) {
225	        BigDecimal totalWeight = BigDecimal.ZERO;
226	        for (var item : request.getItems()) {
227	            Product product = productService.getProduct(item.getSku());
228	            BigDecimal itemWeight = product.getWeightKg().multiply(new BigDecimal(item.getQuantity()));
229	            totalWeight = totalWeight.add(itemWeight);
230	        }
231	        return totalWeight;
232	    }
233	}
234	package com.example.application.service;
235	
236	import com.example.api.dto.CheckoutRequestDto;
237	import com.example.domain.entity.OrderSummary;
238	import com.example.domain.entity.Product;
239	import com.example.domain.enums.*;
240	import org.springframework.stereotype.Service;
241	import java.math.BigDecimal;
242	import java.math.RoundingMode;
243	import java.util.*;
244	
245	@Service
246	public class OrderSummaryCalculator {
247	
248	    private final ProductService productService;
249	    private final TransLogService transLogService;
250	
251	    public OrderSummaryCalculator(ProductService productService, TransLogService transLogService) {
252	        this.productService = productService;
253	        this.transLogService = transLogService;
254	    }
255	
256	    public OrderSummary calculate(CheckoutRequestDto request) {
257	        BigDecimal productsSubtotal = calculateProductsSubtotal(request);
258	        BigDecimal shippingCost = BigDecimal.ZERO;
259	        Integer deliveryDays = 0;
260	
261	        ShippingMethod shippingMethod = ShippingMethod.valueOf(request.getShippingMethod());
262	        Region region = Region.valueOf(request.getRegion());
263	        ClubTier clubTier = ClubTier.valueOf(request.getClubTier());
264	
265	        if (clubTier == ClubTier.GOLD && shippingMethod != ShippingMethod.COURIER && shippingMethod != ShippingMethod.STORE_PICKUP) {
266	            shippingCost = BigDecimal.ZERO;
267	            ShippingQuote quote = getShippingQuote(request, shippingMethod, BigDecimal.ZERO, region);
268	            if (quote != null) {
269	                deliveryDays = quote.days;
270	            }
271	        } else {
272	            ShippingQuote quote = getShippingQuote(request, shippingMethod, BigDecimal.ZERO, region);
273	            if (quote != null) {
274	                shippingCost = quote.cost;
275	                deliveryDays = quote.days;
276	            }
277	        }
278	
279	        BigDecimal couponDiscount = calculateCouponDiscount(request, productsSubtotal, shippingCost, shippingMethod);
280	        BigDecimal insurance = calculateInsurance(productsSubtotal, region);
281	        BigDecimal subtotalBeforePayment = productsSubtotal
282	                .subtract(couponDiscount)
283	                .add(shippingCost)
284	                .add(insurance);
285	
286	        BigDecimal paymentAdjustment = calculatePaymentAdjustment(request, subtotalBeforePayment);
287	        BigDecimal finalTotal = subtotalBeforePayment.add(paymentAdjustment);
288	
289	        Integer installments = request.getInstallments() != null ? request.getInstallments() : 1;
290	        BigDecimal installmentAmount = calculateInstallmentAmount(finalTotal, request.getPaymentMethod(), installments);
291	
292	        BigDecimal nextPurchaseCredit = calculateClubCredit(productsSubtotal, clubTier);
293	        Boolean gift = shouldGift(productsSubtotal, clubTier);
294	
295	        return new OrderSummary(
296	                round(productsSubtotal),
297	                round(couponDiscount),
298	                round(shippingCost),
299	                deliveryDays,
300	                round(insurance),
301	                round(paymentAdjustment),
302	                round(finalTotal),
303	                installments,
304	                round(installmentAmount),
305	                round(nextPurchaseCredit),
306	                gift
307	        );
308	    }
309	
310	    public BigDecimal calculateProductsSubtotal(CheckoutRequestDto request) {
311	        BigDecimal subtotal = BigDecimal.ZERO;
312	        for (var item : request.getItems()) {
313	            Product product = productService.getProduct(item.getSku());
314	            BigDecimal itemTotal = product.getPrice().multiply(new BigDecimal(item.getQuantity()));
315	            subtotal = subtotal.add(itemTotal);
316	        }
317	        return subtotal;
318	    }
319	
320	    private BigDecimal calculateCouponDiscount(CheckoutRequestDto request, BigDecimal productsSubtotal, BigDecimal shippingCost, ShippingMethod shippingMethod) {
321	        if (request.getCoupon() == null || request.getCoupon().isEmpty()) {
322	            return BigDecimal.ZERO;
323	        }
324	
325	        CouponCode coupon = CouponCode.valueOf(request.getCoupon());
326	        BigDecimal discount = BigDecimal.ZERO;
327	
328	        switch (coupon) {
329	            case WELCOME10:
330	                discount = productsSubtotal.multiply(new BigDecimal("0.10"));
331	                break;
332	            case MINUS50:
333	                if (productsSubtotal.compareTo(new BigDecimal("300")) >= 0) {
334	                    discount = new BigDecimal("50");
335	                }
336	                break;
337	            case FREESHIPPING:
338	                if (shippingMethod != ShippingMethod.STORE_PICKUP) {
339	                    discount = shippingCost;
340	                }
341	                break;
342	            case BUY3PAY2:
343	                discount = calculateBuy3Pay2Discount(request, productsSubtotal);
344	                break;
345	        }
346	
347	        BigDecimal maxDiscount = productsSubtotal.multiply(new BigDecimal("0.30"));
348	        if (discount.compareTo(maxDiscount) > 0) {
349	            discount = maxDiscount;
350	        }
351	
352	        return discount;
353	    }
354	
355	    private BigDecimal calculateBuy3Pay2Discount(CheckoutRequestDto request, BigDecimal productsSubtotal) {
356	        BigDecimal discount = BigDecimal.ZERO;
357	
358	        Map<String, Integer> skuQuantities = new HashMap<>();
359	        for (var item : request.getItems()) {
360	            skuQuantities.put(item.getSku(), item.getQuantity());
361	        }
362	
363	        for (var entry : skuQuantities.entrySet()) {
364	            int quantity = entry.getValue();
365	            int freeUnits = quantity / 3;
366	            if (freeUnits > 0) {
367	                Product product = productService.getProduct(entry.getKey());
368	                discount = discount.add(product.getPrice().multiply(new BigDecimal(freeUnits)));
369	            }
370	        }
371	
372	        return discount;
373	    }
374	
375	    private ShippingQuote getShippingQuote(CheckoutRequestDto request, ShippingMethod method, BigDecimal currentCost, Region region) {
376	        ShippingQuote baseQuote = null;
377	
378	        switch (method) {
379	            case ECONOMY:
380	            case EXPRESS:
381	                baseQuote = transLogService.getQuote(request.getZipCode(), calculateTotalWeight(request), method);
382	                break;
383	            case STORE_PICKUP:
384	                baseQuote = new ShippingQuote(BigDecimal.ZERO, 1);
385	                break;
386	            case COURIER:
387	                BigDecimal totalWeight = calculateTotalWeight(request);
388	                if (totalWeight.compareTo(new BigDecimal("5")) > 0) {
389	                    return null;
390	                }
391	                baseQuote = new ShippingQuote(new BigDecimal("18"), 0);
392	                break;
393	            default:
394	                return null;
395	        }
396	
397	        if (baseQuote != null) {
398	            int adjustedDays = calculateDeliveryDays(method, region, baseQuote.days);
399	            return new ShippingQuote(baseQuote.cost, adjustedDays);
400	        }
401	
402	        return baseQuote;
403	    }
404	
405	    private Integer calculateDeliveryDays(ShippingMethod method, Region region, int baseDeliveryDays) {
406	        int days = baseDeliveryDays;
407	
408	        if (method == ShippingMethod.ECONOMY || method == ShippingMethod.EXPRESS) {
409	            if (region == Region.NORTH) {
410	                days += 3;
411	            } else if (region == Region.NORTHEAST) {
412	                days += 2;
413	            }
414	        }
415	
416	        return days;
417	    }
418	
419	    private BigDecimal calculateTotalWeight(CheckoutRequestDto request) {
420	        BigDecimal totalWeight = BigDecimal.ZERO;
421	        for (var item : request.getItems()) {
422	            Product product = productService.getProduct(item.getSku());
423	            BigDecimal itemWeight = product.getWeightKg().multiply(new BigDecimal(item.getQuantity()));
424	            totalWeight = totalWeight.add(itemWeight);
425	        }
426	        return totalWeight;
427	    }
428	
429	    private BigDecimal calculateInsurance(BigDecimal productsSubtotal, Region region) {
430	        BigDecimal percentage;
431	        BigDecimal limit;
432	
433	        switch (region) {
434	            case SOUTHEAST, SOUTH:
435	                percentage = new BigDecimal("0.01");
436	                limit = null;
437	                break;
438	            case MIDWEST:
439	                percentage = new BigDecimal("0.015");
440	                limit = null;
441	                break;
442	            case NORTH:
443	                percentage = new BigDecimal("0.025");
444	                limit = new BigDecimal("30");
445	                break;
446	            case NORTHEAST:
447	                percentage = new BigDecimal("0.02");
448	                limit = new BigDecimal("30");
449	                break;
450	            default:
451	                return BigDecimal.ZERO;
452	        }
453	
454	        BigDecimal insurance = productsSubtotal.multiply(percentage);
455	        if (limit != null && insurance.compareTo(limit) > 0) {
456	            insurance = limit;
457	        }
458	
459	        return insurance;
460	    }
461	
462	    private BigDecimal calculatePaymentAdjustment(CheckoutRequestDto request, BigDecimal subtotal) {
463	        PaymentMethod method = PaymentMethod.valueOf(request.getPaymentMethod());
464	        Integer installments = request.getInstallments() != null ? request.getInstallments() : 1;
465	
466	        switch (method) {
467	            case PIX:
468	                if (request.getCoupon() == null || request.getCoupon().isEmpty()) {
469	                    return subtotal.multiply(new BigDecimal("0.05")).negate();
470	                }
471	                return BigDecimal.ZERO;
472	            case CREDIT_CARD:
473	                if (installments <= 3) {
474	                    return BigDecimal.ZERO;
475	                }
476	                return calculateCreditCardInterest(subtotal, installments);
477	            case BANK_SLIP:
478	                return new BigDecimal("3.49");
479	            default:
480	                return BigDecimal.ZERO;
481	        }
482	    }
483	
484	    private BigDecimal calculateCreditCardInterest(BigDecimal total, Integer installments) {
485	        BigDecimal monthlyRate = new BigDecimal("0.0199");
486	        BigDecimal installmentAmount = total
487	                .multiply(monthlyRate)
488	                .divide(
489	                        BigDecimal.ONE.subtract(
490	                                BigDecimal.ONE.add(monthlyRate).pow(-installments)
491	                        ),
492	                        10,
493	                        RoundingMode.HALF_EVEN
494	                );
495	
496	        BigDecimal totalWithInterest = installmentAmount.multiply(new BigDecimal(installments));
497	        return totalWithInterest.subtract(total);
498	    }
499	
500	    private BigDecimal calculateInstallmentAmount(BigDecimal finalTotal, String paymentMethod, Integer installments) {
501	        PaymentMethod method = PaymentMethod.valueOf(paymentMethod);
502	
503	        if (method == PaymentMethod.CREDIT_CARD && installments > 3) {
504	            BigDecimal monthlyRate = new BigDecimal("0.0199");
505	            return finalTotal
506	                    .multiply(monthlyRate)
507	                    .divide(
508	                            BigDecimal.ONE.subtract(
509	                                    BigDecimal.ONE.add(monthlyRate).pow(-installments)
510	                            ),
511	                            2,
512	                            RoundingMode.HALF_EVEN
513	                    );
514	        }
515	
516	        return finalTotal.divide(new BigDecimal(installments), 2, RoundingMode.HALF_EVEN);
517	    }
518	
519	    private BigDecimal calculateClubCredit(BigDecimal productsSubtotal, ClubTier tier) {
520	        switch (tier) {
521	            case SILVER:
522	                return productsSubtotal.multiply(new BigDecimal("0.02"));
523	            case GOLD:
524	                return productsSubtotal.multiply(new BigDecimal("0.05"));
525	            default:
526	                return BigDecimal.ZERO;
527	        }
528	    }
529	
530	    private Boolean shouldGift(BigDecimal productsSubtotal, ClubTier tier) {
531	        if (tier == ClubTier.GOLD && productsSubtotal.compareTo(new BigDecimal("500")) > 0) {
532	            return true;
533	        }
534	        return false;
535	    }
536	
537	    private BigDecimal round(BigDecimal value) {
538	        return value.setScale(2, RoundingMode.HALF_EVEN);
539	    }
540	
541	    public static class ShippingQuote {
542	        public BigDecimal cost;
543	        public Integer days;
544	
545	        public ShippingQuote(BigDecimal cost, Integer days) {
546	            this.cost = cost;
547	            this.days = days;
548	        }
549	    }
550	}

