 83	        try {
 84	            method = ShippingMethod.valueOf(request.getShippingMethod());
 85	        } catch (IllegalArgumentException e) {
 86	            throw new InvalidShippingMethodException();
 87	        }
 88	
 89	        if (method == ShippingMethod.COURIER) {
