115	    private void validatePaymentMethod(CheckoutRequestDto request) {
116	        PaymentMethod method;
117	        try {
118	            method = PaymentMethod.valueOf(request.getPaymentMethod());
119	        } catch (IllegalArgumentException e) {
120	            throw new InvalidPaymentMethodException();
121	        }
122	
123	        Integer installments = request.getInstallments() != null ? request.getInstallments() : 1;
