 19	    public void validateCheckout(CheckoutRequestDto request) {
 20	        validateItems(request);
 21	        validateCustomer(request);
 22	        validateRegion(request);
 23	        validateZipCode(request);
 24	        validateShippingMethod(request);
 25	        validateClubTier(request);
 26	        validateCoupon(request);
