156	
157	public class CouponValidator {
158	
159	    private final OrderRepository orderRepository;
160	
161	    public CouponValidator(OrderRepository orderRepository) {
162	        this.orderRepository = orderRepository;
163	    }
164	
165	    public void validate(CheckoutRequestDto request, BigDecimal productsSubtotal) {
166	        if (request.getCoupon() == null || request.getCoupon().isEmpty()) {
167	            return;
168	        }
169	
170	        CouponCode coupon = CouponCode.valueOf(request.getCoupon());
171	
172	        switch (coupon) {
173	            case WELCOME10:
174	                validateWelcome10(request);
175	                break;
176	            case MINUS50:
177	                validateMinus50(productsSubtotal);
178	                break;
179	            case FREESHIPPING:
180	                validateFreeShipping(request);
181	                break;
182	            case BUY3PAY2:
183	                break;
184	        }
185	    }
186	
187	    private void validateWelcome10(CheckoutRequestDto request) {
188	        String cpf = request.getCustomer().getCpf();
189	        List<Order> customerOrders = orderRepository.findAll();
190	        boolean hasPaidOrder = customerOrders.stream()
191	                .anyMatch(o -> o.getCustomerCpf().equals(cpf) &&
192	                        (o.getStatus().name().equals("PAID") ||
193	                         o.getStatus().name().equals("SHIPPED") ||
194	                         o.getStatus().name().equals("DELIVERED")));
195	
196	        if (hasPaidOrder) {
197	            throw new CouponNotApplicableException();
198	        }
199	    }
200	
201	    private void validateMinus50(BigDecimal productsSubtotal) {
202	        if (productsSubtotal.compareTo(new BigDecimal("300")) < 0) {
203	            throw new CouponNotApplicableException();
204	        }
205	    }
206	
207	    private void validateFreeShipping(CheckoutRequestDto request) {
208	        ShippingMethod method = ShippingMethod.valueOf(request.getShippingMethod());
209	        if (method == ShippingMethod.STORE_PICKUP) {
210	            throw new CouponNotApplicableException();
211	        }
212	    }
213	}
