147	        return ResponseEntity.ok(convertToDto(order));
148	    }
149	
150	    @PostMapping("/{id}/payment")
151	    public ResponseEntity<OrderDto> recordPayment(@PathVariable String id, @RequestBody PaymentRequestDto paymentRequest) {
152	        Order order = orderService.processPayment(id, paymentRequest);
153	        return ResponseEntity.ok(convertToDto(order));
154	    }
155	
156	    @PostMapping("/{id}/shipment")
157	    public ResponseEntity<OrderDto> recordShipment(@PathVariable String id, @RequestBody ShipmentRequestDto shipmentRequest) {
158	        Order order = orderService.shipOrder(id, shipmentRequest);
159	        return ResponseEntity.ok(convertToDto(order));
160	    }
161	
162	    @PostMapping("/{id}/delivery")
163	    public ResponseEntity<OrderDto> recordDelivery(@PathVariable String id) {
164	        Order order = orderService.deliverOrder(id);
165	        return ResponseEntity.ok(convertToDto(order));
166	    }
167	
168	    @PostMapping("/{id}/cancellation")
