174	    private OrderDto convertToDto(Order order) {
175	        OrderSummary summary = order.getSummary();
176	        SummaryDto summaryDto = new SummaryDto(
177	                summary.getProductsSubtotal(),
178	                summary.getCouponDiscount(),
179	                summary.getShippingCost(),
180	                summary.getDeliveryDays(),
181	                summary.getInsurance(),
182	                summary.getPaymentAdjustment(),
183	                summary.getFinalTotal(),
184	                summary.getInstallments(),
185	                summary.getInstallmentAmount(),
186	                summary.getNextPurchaseCredit(),
187	                summary.getGift()
188	        );
189	
190	        var itemDtos = order.getItems().stream()
191	                .map(item -> new OrderItemDto(item.getSku(), item.getQuantity()))
192	                .toList();
193	
194	        return new OrderDto(
195	                order.getId(),
196	                order.getStatus().name(),
197	                order.getCreatedAt(),
198	                summaryDto,
