422	import java.util.Map;
424	@Converter(autoApply = true)
425	public class OrderSummaryConverter implements AttributeConverter<OrderSummary, String> {
427	    private static final ObjectMapper mapper = new ObjectMapper();
429	    @Override
430	    public String convertToDatabaseColumn(OrderSummary attribute) {
431	        if (attribute == null) {
432	            return null;
433	        }
434	        try {
435	            Map<String, Object> map = new LinkedHashMap<>();
436	            map.put("productsSubtotal", attribute.getProductsSubtotal());
437	            map.put("couponDiscount", attribute.getCouponDiscount());
438	            map.put("shippingCost", attribute.getShippingCost());
439	            map.put("deliveryDays", attribute.getDeliveryDays());
440	            map.put("insurance", attribute.getInsurance());
441	            map.put("paymentAdjustment", attribute.getPaymentAdjustment());
442	            map.put("finalTotal", attribute.getFinalTotal());
443	            map.put("installments", attribute.getInstallments());
444	            map.put("installmentAmount", attribute.getInstallmentAmount());
445	            map.put("nextPurchaseCredit", attribute.getNextPurchaseCredit());
446	            map.put("gift", attribute.getGift());
447	            return mapper.writeValueAsString(map);
448	        } catch (JsonProcessingException e) {
449	            throw new RuntimeException(e);
450	        }
451	    }
453	    @Override
454	    public OrderSummary convertToEntityAttribute(String dbData) {
455	        if (dbData == null) {
456	            return null;
457	        }
458	        try {
459	            @SuppressWarnings("unchecked")
460	            Map<String, Object> map = mapper.readValue(dbData, Map.class);
461	            return new OrderSummary(
462	                    new BigDecimal(map.get("productsSubtotal").toString()),
463	                    new BigDecimal(map.get("couponDiscount").toString()),
464	                    new BigDecimal(map.get("shippingCost").toString()),
465	                    ((Number) map.get("deliveryDays")).intValue(),
466	                    new BigDecimal(map.get("insurance").toString()),
467	                    new BigDecimal(map.get("paymentAdjustment").toString()),
468	                    new BigDecimal(map.get("finalTotal").toString()),
469	                    ((Number) map.get("installments")).intValue(),
470	                    new BigDecimal(map.get("installmentAmount").toString()),
471	                    new BigDecimal(map.get("nextPurchaseCredit").toString()),
472	                    (Boolean) map.get("gift")
473	            );
474	        } catch (JsonProcessingException e) {
475	            throw new RuntimeException(e);
476	        }
477	    }
478	}

