import java.nio.charset.StandardCharsets;
import java.util.*;

public class Stub {
    static volatile String body = "{\"price_cents\": 3310, \"eta_hours\": 41}";
    static volatile int status = 200;
    static volatile long delay = 0;
    static final List<String> log = Collections.synchronizedList(new ArrayList<>());
    public static void main(String[] a) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress(Integer.parseInt(a[0])), 0);
        s.setExecutor(java.util.concurrent.Executors.newCachedThreadPool());
        s.createContext("/v2/quote", ex -> {
            log.add(ex.getRequestURI().toString());
            try { Thread.sleep(delay); } catch (InterruptedException e) {}
            byte[] b = body.getBytes(StandardCharsets.UTF_8);
            ex.getResponseHeaders().add("Content-Type", "application/json");
            ex.sendResponseHeaders(status, b.length);
            ex.getResponseBody().write(b); ex.close();
        });
        s.createContext("/set", ex -> {
            String q = ex.getRequestURI().getRawQuery();
            for (String p : q.split("&")) {
                String[] kv = p.split("=", 2);
                String v = URLDecoder.decode(kv[1], StandardCharsets.UTF_8);
                if (kv[0].equals("body")) body = v;
                if (kv[0].equals("status")) status = Integer.parseInt(v);
                if (kv[0].equals("delay")) delay = Long.parseLong(v);
            }
            byte[] b = "ok".getBytes(); ex.sendResponseHeaders(200, b.length); ex.getResponseBody().write(b); ex.close();
        });
        s.createContext("/log", ex -> {
            String out; synchronized (log) { out = String.join("\n", log); log.clear(); }
            byte[] b = out.getBytes(); ex.sendResponseHeaders(200, b.length); ex.getResponseBody().write(b); ex.close();
        });
        s.start();
    }
}
